// -- deps.js --

// Lazy dependency loading for optional format parsers
// OL + proj4 are vendored (prepended by build.js), always available.

const PAPA_JS = 'https://cdn.jsdelivr.net/npm/papaparse@5/papaparse.min.js';
const SHP_JS = 'https://cdn.jsdelivr.net/npm/shpjs@6/dist/shp.min.js';

function injectScript(url) {
  return new Promise((resolve, reject) => {
    if (document.querySelector(`script[src="${url}"]`)) { resolve(); return; }
    const s = document.createElement('script');
    s.src = url;
    s.onload = resolve;
    s.onerror = () => reject(new Error(`Failed to load ${url}`));
    document.head.appendChild(s);
  });
}

async function ensurePapa() {
  if (window.Papa) return;
  await injectScript(PAPA_JS);
}

async function ensureShp() {
  if (window.shp) return;
  await injectScript(SHP_JS);
}

// -- proj.js --

// Projection registration helper

function registerProj(code, def) {
  proj4.defs(code, def);
  ol.proj.proj4.register(proj4);
}

// -- render.js --

// Default styles, terrain color ramp, hillshade

function defaultPointStyle() {
  return new ol.style.Style({
    image: new ol.style.Circle({
      radius: 6,
      fill: new ol.style.Fill({ color: 'rgba(200, 155, 60, 0.8)' }),
      stroke: new ol.style.Stroke({ color: '#c89b3c', width: 1.5 })
    })
  });
}

function defaultLineStyle() {
  return new ol.style.Style({
    stroke: new ol.style.Stroke({ color: '#c89b3c', width: 2 })
  });
}

function defaultPolygonStyle() {
  return new ol.style.Style({
    stroke: new ol.style.Stroke({ color: '#c89b3c', width: 2 }),
    fill: new ol.style.Fill({ color: 'rgba(200, 155, 60, 0.15)' })
  });
}

function defaultStyle() {
  const pt = defaultPointStyle();
  const ln = defaultLineStyle();
  const pg = defaultPolygonStyle();
  return function(feature) {
    const geom = feature.getGeometry();
    if (!geom) return pg;
    const type = geom.getType();
    if (type === 'Point' || type === 'MultiPoint') return pt;
    if (type === 'LineString' || type === 'MultiLineString') return ln;
    return pg;
  };
}

// Terrain color ramp — returns [r, g, b] for normalized t in [0, 1]
const TERRAIN_STOPS = [
  [0,    34, 139, 34],     // forest green
  [0.15, 85, 153, 68],
  [0.3,  170, 160, 80],
  [0.5,  185, 152, 100],   // brown
  [0.7,  190, 170, 140],
  [0.85, 220, 220, 220],   // light gray
  [1.0,  255, 255, 255],   // white
];

function terrainColor(t) {
  if (t <= 0) return [TERRAIN_STOPS[0][1], TERRAIN_STOPS[0][2], TERRAIN_STOPS[0][3]];
  if (t >= 1) { const s = TERRAIN_STOPS[TERRAIN_STOPS.length - 1]; return [s[1], s[2], s[3]]; }
  for (let i = 1; i < TERRAIN_STOPS.length; i++) {
    if (t <= TERRAIN_STOPS[i][0]) {
      const f = (t - TERRAIN_STOPS[i - 1][0]) / (TERRAIN_STOPS[i][0] - TERRAIN_STOPS[i - 1][0]);
      const a = TERRAIN_STOPS[i - 1], b = TERRAIN_STOPS[i];
      return [
        Math.round(a[1] + f * (b[1] - a[1])),
        Math.round(a[2] + f * (b[2] - a[2])),
        Math.round(a[3] + f * (b[3] - a[3]))
      ];
    }
  }
  return [255, 255, 255];
}

// Render DEM data to a canvas with terrain colors + simple hillshade
// Canvas is capped at MAX_RENDER pixels per side to avoid freezing the main thread.
const MAX_RENDER = 2048;

function renderDEMCanvas(dem) {
  const { data, width, height, min, max, nodata } = dem;

  // Downsample if the DEM is larger than MAX_RENDER
  const scale = Math.min(1, MAX_RENDER / Math.max(width, height));
  const cw = Math.round(width * scale);
  const ch = Math.round(height * scale);

  const canvas = document.createElement('canvas');
  canvas.width = cw;
  canvas.height = ch;
  const ctx = canvas.getContext('2d');
  const img = ctx.createImageData(cw, ch);
  const px = img.data;
  const range = max - min || 1;

  for (let r = 0; r < ch; r++) {
    // Map canvas row to DEM row
    const sr = Math.min(((r + 0.5) / ch * height) | 0, height - 1);
    for (let c = 0; c < cw; c++) {
      const sc = Math.min(((c + 0.5) / cw * width) | 0, width - 1);
      const si = sr * width + sc;
      const v = data[si];
      const idx = (r * cw + c) * 4;
      if (v === nodata) {
        px[idx + 3] = 0;
      } else {
        // Simple hillshade from neighbors in source grid
        let shade = 1;
        if (sc > 0 && sc < width - 1 && sr > 0 && sr < height - 1) {
          const dzdx = data[sr * width + sc + 1] - data[sr * width + sc - 1];
          const dzdy = data[(sr + 1) * width + sc] - data[(sr - 1) * width + sc];
          shade = 0.5 + 0.5 * (dzdy - dzdx) / Math.sqrt(dzdx * dzdx + dzdy * dzdy + 4);
        }
        const t = (v - min) / range;
        const [cr2, cg, cb] = terrainColor(t);
        px[idx]     = Math.min(255, Math.max(0, cr2 * shade));
        px[idx + 1] = Math.min(255, Math.max(0, cg * shade));
        px[idx + 2] = Math.min(255, Math.max(0, cb * shade));
        px[idx + 3] = 190;
      }
    }
  }

  ctx.putImageData(img, 0, 0);
  return canvas;
}

// -- dem.js --

// DEM data access, bilinear sampling, profile extraction

class DEM {
  constructor(data, width, height, bbox) {
    this.data = data;       // Float32Array
    this.width = width;
    this.height = height;
    this.bbox = bbox;       // [west, south, east, north]
    this.nodata = -9999;

    // Compute min/max (excluding nodata)
    let min = Infinity, max = -Infinity;
    for (let i = 0; i < data.length; i++) {
      const v = data[i];
      if (v !== this.nodata) {
        if (v < min) min = v;
        if (v > max) max = v;
      }
    }
    this.min = min === Infinity ? 0 : min;
    this.max = max === -Infinity ? 0 : max;
  }

  // Bilinear interpolation at (lat, lon)
  sample(lat, lon) {
    const [west, south, east, north] = this.bbox;
    if (lon < west || lon > east || lat < south || lat > north) return null;

    // Convert to pixel coordinates
    // Row 0 = north edge, row (height-1) = south edge
    const px = (lon - west) / (east - west) * (this.width - 1);
    const py = (north - lat) / (north - south) * (this.height - 1);

    const x0 = Math.floor(px);
    const y0 = Math.floor(py);
    const x1 = Math.min(x0 + 1, this.width - 1);
    const y1 = Math.min(y0 + 1, this.height - 1);

    const fx = px - x0;
    const fy = py - y0;

    const v00 = this.data[y0 * this.width + x0];
    const v10 = this.data[y0 * this.width + x1];
    const v01 = this.data[y1 * this.width + x0];
    const v11 = this.data[y1 * this.width + x1];

    // Skip nodata pixels
    if (v00 === this.nodata || v10 === this.nodata ||
        v01 === this.nodata || v11 === this.nodata) {
      // Fallback: nearest neighbor among valid values
      const candidates = [v00, v10, v01, v11].filter(v => v !== this.nodata);
      return candidates.length > 0 ? candidates[0] : null;
    }

    // Bilinear interpolation
    const top = v00 * (1 - fx) + v10 * fx;
    const bot = v01 * (1 - fx) + v11 * fx;
    return top * (1 - fy) + bot * fy;
  }

  // Extract elevation profile between two points
  profile(latA, lonA, latB, lonB, opts = {}) {
    const samples = opts.samples || 500;

    const dist = new Float64Array(samples);
    const elev = new Float32Array(samples);
    const lat = new Float64Array(samples);
    const lon = new Float64Array(samples);

    for (let i = 0; i < samples; i++) {
      const t = i / (samples - 1);
      lat[i] = latA + t * (latB - latA);
      lon[i] = lonA + t * (lonB - lonA);
      elev[i] = this.sample(lat[i], lon[i]) ?? this.nodata;
      dist[i] = i === 0 ? 0 : dist[i - 1] + haversine(lat[i - 1], lon[i - 1], lat[i], lon[i]);
    }

    return { dist, elev, lat, lon };
  }
}

// Haversine distance in meters
function haversine(lat1, lon1, lat2, lon2) {
  const R = 6371000;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// -- map.js --

// Map creation, basemap management, controls


const BASEMAPS = {
  topo: 'https://tile.opentopomap.org/{z}/{x}/{y}.png',
  osm: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
  satellite: 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'
};

// Coordinate display overlay — dark monospace badge, bottom-left
function createCoordDisplay(mapEl) {
  const div = document.createElement('div');
  div.style.cssText = `
    position:absolute; bottom:8px; left:8px; z-index:10;
    background:rgba(0,0,0,0.7); color:#c89b3c; padding:2px 6px;
    font:11px monospace; border-radius:3px; pointer-events:none;
  `;
  mapEl.style.position = 'relative';
  mapEl.appendChild(div);
  return div;
}

function createMap(target, opts = {}) {
  const center = opts.center || [0, 0]; // [lon, lat]
  const zoom = opts.zoom || 2;
  const basemap = opts.basemap || 'topo';

  // Resolve target element
  let el;
  if (!target) {
    el = document.createElement('div');
    el.style.width = '100%';
    el.style.height = '600px';
    // Append to current cell output if available
    if (opts._output) {
      opts._output.appendChild(el);
    } else {
      document.body.appendChild(el);
    }
  } else if (typeof target === 'string') {
    el = document.querySelector(target);
    if (!el) throw new Error(`Map target not found: ${target}`);
  } else {
    el = target;
  }

  // Basemap tile layer
  const tileUrl = BASEMAPS[basemap] || basemap;
  const baseLayer = new ol.layer.Tile({
    source: new ol.source.XYZ({ url: tileUrl, crossOrigin: 'anonymous' })
  });

  const view = new ol.View({
    center: ol.proj.fromLonLat(center),
    zoom: zoom
  });

  const controls = [];

  // Scale bar
  if (opts.scalebar !== false) {
    controls.push(new ol.control.ScaleLine({
      units: opts.scaleUnits || 'metric'
    }));
  }

  const map = new ol.Map({
    target: el,
    layers: [baseLayer],
    view: view,
    controls: ol.Map.prototype.getControls ? undefined : controls
  });

  // Add controls after construction (OL default controls may vary)
  for (const c of controls) map.addControl(c);

  // Coordinate display
  let coordDiv = null;
  if (opts.coordinates !== false) {
    coordDiv = createCoordDisplay(el);
    map.on('pointermove', (e) => {
      const [lon, lat] = ol.proj.toLonLat(e.coordinate);
      coordDiv.textContent = `${lat.toFixed(4)}, ${lon.toFixed(4)}`;
    });
    map.getViewport().addEventListener('mouseout', () => {
      coordDiv.textContent = '';
    });
  }

  // Map wrapper object
  const wrapper = {
    ol: map,
    el: el,
    _layers: [],

    get bounds() {
      const ext = view.calculateExtent(map.getSize());
      const [w, s] = ol.proj.toLonLat([ext[0], ext[1]]);
      const [e, n] = ol.proj.toLonLat([ext[2], ext[3]]);
      return [w, s, e, n];
    },

    get center() {
      return ol.proj.toLonLat(view.getCenter());
    },

    set center(lonLat) {
      view.setCenter(ol.proj.fromLonLat(lonLat));
    },

    get zoom() {
      return view.getZoom();
    },

    set zoom(z) {
      view.setZoom(z);
    },

    fitBounds(bbox, padding = 50) {
      const ext = ol.proj.transformExtent(
        [bbox[0], bbox[1], bbox[2], bbox[3]],
        'EPSG:4326', view.getProjection()
      );
      view.fit(ext, { padding: [padding, padding, padding, padding], maxZoom: 18 });
    },

    setBasemap(name) {
      const url = BASEMAPS[name] || name;
      baseLayer.getSource().setUrl(url);
    },

    exportImage(type = 'image/png') {
      return new Promise((resolve) => {
        map.once('rendercomplete', () => {
          const canvas = document.createElement('canvas');
          const size = map.getSize();
          canvas.width = size[0];
          canvas.height = size[1];
          const ctx = canvas.getContext('2d');
          for (const c of map.getViewport().querySelectorAll('.ol-layer canvas, canvas.ol-layer')) {
            if (c.width > 0) {
              ctx.globalAlpha = c.parentNode?.style?.opacity || c.style.opacity || 1;
              const transform = c.style.transform;
              const match = transform?.match(/matrix\(([^)]+)\)/);
              if (match) {
                const vals = match[1].split(',').map(Number);
                ctx.setTransform(vals[0], vals[1], vals[2], vals[3], vals[4], vals[5]);
              }
              ctx.drawImage(c, 0, 0);
              ctx.setTransform(1, 0, 0, 1, 0, 0);
              ctx.globalAlpha = 1;
            }
          }
          resolve(canvas.toDataURL(type));
        });
        map.renderSync();
      });
    },

    async measure(type = 'distance') {
      const olType = type === 'area' ? 'Polygon' : 'LineString';
      const source = new ol.source.Vector();
      const layer = new ol.layer.Vector({
        source,
        style: new ol.style.Style({
          stroke: new ol.style.Stroke({ color: '#c89b3c', width: 2, lineDash: [6, 4] }),
          fill: new ol.style.Fill({ color: 'rgba(200, 155, 60, 0.1)' })
        })
      });
      map.addLayer(layer);
      const draw = new ol.interaction.Draw({ source, type: olType });
      map.addInteraction(draw);

      return new Promise((resolve) => {
        draw.on('drawend', (e) => {
          map.removeInteraction(draw);
          const geom = e.feature.getGeometry();

          if (type === 'area') {
            const coords = geom.getCoordinates()[0].map(c => ol.proj.toLonLat(c));
            // Shoelace on sphere via triangles from centroid (approximate for small polygons)
            const area = sphericalArea(coords);
            resolve({ area, unit: 'm\u00b2', coords, geometry: geom, layer });
          } else {
            const coords = geom.getCoordinates().map(c => ol.proj.toLonLat(c));
            let dist = 0;
            for (let i = 1; i < coords.length; i++) {
              dist += haversine(coords[i - 1][1], coords[i - 1][0], coords[i][1], coords[i][0]);
            }
            resolve({ distance: dist, unit: 'm', coords, geometry: geom, layer });
          }
        });
      });
    }
  };

  // Force map to recalculate size after DOM settles
  setTimeout(() => map.updateSize(), 100);

  return wrapper;
}

// Spherical polygon area via spherical excess (Girard's theorem)
function sphericalArea(coords) {
  const R = 6371000;
  const rad = Math.PI / 180;
  const n = coords.length - 1; // last == first for closed ring
  if (n < 3) return 0;

  let total = 0;
  for (let i = 0; i < n; i++) {
    const [lon1, lat1] = coords[i];
    const [lon2, lat2] = coords[(i + 1) % n];
    total += (lon2 - lon1) * rad * (2 + Math.sin(lat1 * rad) + Math.sin(lat2 * rad));
  }
  return Math.abs(total * R * R / 2);
}

// -- layers.js --

// SpxLayer class and layer panel UI

class SpxLayer {
  constructor(olLayer, opts = {}) {
    this.ol = olLayer;
    this.name = opts.name || 'Layer';
    this.type = opts.type || 'unknown';
    this._bounds = opts.bounds || null;
    this.data = opts.data || null;
    this._map = opts.map || null;
  }

  get visible() { return this.ol.getVisible(); }
  set visible(v) { this.ol.setVisible(v); }

  get bounds() {
    if (this._bounds) return this._bounds;
    const src = this.ol.getSource();
    if (src && typeof src.getExtent === 'function') {
      const ext = src.getExtent();
      if (ext && isFinite(ext[0])) {
        const [w, s] = ol.proj.toLonLat([ext[0], ext[1]]);
        const [e, n] = ol.proj.toLonLat([ext[2], ext[3]]);
        return [w, s, e, n];
      }
    }
    return null;
  }

  show() { this.ol.setVisible(true); }
  hide() { this.ol.setVisible(false); }

  remove() {
    if (this._map) {
      this._map.ol.removeLayer(this.ol);
      const idx = this._map._layers.indexOf(this);
      if (idx >= 0) this._map._layers.splice(idx, 1);
      updateLayerPanel(this._map);
    }
  }

  zoomTo() {
    const b = this.bounds;
    if (b && this._map) {
      this._map.fitBounds(b);
    }
  }
}

// Floating layer panel (top-right corner)
const PANEL_STYLE = `
  position: absolute; top: 10px; right: 10px; z-index: 100;
  background: rgba(30, 30, 30, 0.9); border: 1px solid #555;
  border-radius: 4px; padding: 6px 8px; min-width: 140px;
  font: 12px monospace; color: #ccc; max-height: 300px; overflow-y: auto;
`;
const ITEM_STYLE = `
  padding: 3px 4px; cursor: pointer; display: flex; align-items: center; gap: 6px;
  border-radius: 2px;
`;

function addLayerPanel(map) {
  if (map._layerPanel) return;
  const panel = document.createElement('div');
  panel.style.cssText = PANEL_STYLE;
  panel.innerHTML = '<div style="color:#c89b3c;margin-bottom:4px;font-weight:bold">Layers</div>';
  map.el.style.position = 'relative';
  map.el.appendChild(panel);
  map._layerPanel = panel;
}

function updateLayerPanel(map) {
  if (!map._layerPanel) return;
  const panel = map._layerPanel;
  // Keep header, rebuild items
  const header = panel.firstElementChild;
  panel.innerHTML = '';
  panel.appendChild(header);

  for (const lyr of map._layers) {
    const item = document.createElement('div');
    item.style.cssText = ITEM_STYLE;
    item.onmouseover = () => item.style.background = 'rgba(200,155,60,0.15)';
    item.onmouseout = () => item.style.background = 'none';

    const cb = document.createElement('input');
    cb.type = 'checkbox';
    cb.checked = lyr.visible;
    cb.onchange = () => { lyr.visible = cb.checked; };

    const label = document.createElement('span');
    label.textContent = lyr.name;
    label.style.flex = '1';
    label.ondblclick = () => lyr.zoomTo();

    item.appendChild(cb);
    item.appendChild(label);
    panel.appendChild(item);
  }
}

function registerLayer(map, layer) {
  map._layers.push(layer);
  if (!map._layerPanel) addLayerPanel(map);
  updateLayerPanel(map);
}

// -- loaders.js --

// Format loaders: CSV, GeoJSON, Shapefile, GeoTIFF




// -- CSV loader --

const LON_PATTERNS = /^(lon|longitude|lng|x|easting|long|coordx)$/i;
const LAT_PATTERNS = /^(lat|latitude|y|northing|coordy)$/i;

function detectColumn(headers, pattern) {
  for (const h of headers) {
    if (pattern.test(h.trim())) return h;
  }
  return null;
}

async function loadCSV(map, source, opts = {}) {

  await ensurePapa();

  // Parse CSV
  let text;
  if (typeof source === 'string') {
    // URL or raw CSV text
    if (source.startsWith('http')) {
      const resp = await fetch(source);
      text = await resp.text();
    } else {
      text = source;
    }
  } else if (source instanceof File || source instanceof Blob) {
    text = await source.text();
  } else {
    throw new Error('CSV source must be a string, URL, File, or Blob');
  }

  const parsed = Papa.parse(text, { header: true, skipEmptyLines: true, dynamicTyping: true });
  const rows = parsed.data;
  const headers = parsed.meta.fields;

  // Detect coordinate columns
  const lonCol = opts.lon || detectColumn(headers, LON_PATTERNS);
  const latCol = opts.lat || detectColumn(headers, LAT_PATTERNS);

  if (!lonCol || !latCol) {
    // Return data without spatial rendering
    const layer = new SpxLayer(new ol.layer.Vector({ source: new ol.source.Vector() }), {
      name: opts.name || 'CSV', type: 'csv', map, data: rows
    });
    registerLayer(map, layer);
    return layer;
  }

  // Create point features
  const features = [];
  for (const row of rows) {
    const lon = parseFloat(row[lonCol]);
    const lat = parseFloat(row[latCol]);
    if (isNaN(lon) || isNaN(lat)) continue;
    const feature = new ol.Feature({
      geometry: new ol.geom.Point(ol.proj.fromLonLat([lon, lat]))
    });
    // Copy row properties to feature
    for (const key of headers) {
      if (key !== lonCol && key !== latCol) feature.set(key, row[key]);
    }
    feature.set('_lon', lon);
    feature.set('_lat', lat);
    features.push(feature);
  }

  const vectorSource = new ol.source.Vector({ features });
  const vectorLayer = new ol.layer.Vector({
    source: vectorSource,
    style: defaultStyle()
  });

  map.ol.addLayer(vectorLayer);

  const layer = new SpxLayer(vectorLayer, {
    name: opts.name || 'CSV',
    type: 'csv',
    map,
    data: rows
  });
  registerLayer(map, layer);
  return layer;
}

// -- GeoJSON loader --

async function loadGeoJSON(map, data, opts = {}) {


  const geojson = typeof data === 'string' ? JSON.parse(data) : data;
  const format = new ol.format.GeoJSON();
  const features = format.readFeatures(geojson, {
    featureProjection: map.ol.getView().getProjection(),
    dataProjection: opts.crs || 'EPSG:4326'
  });

  const vectorSource = new ol.source.Vector({ features });
  const vectorLayer = new ol.layer.Vector({
    source: vectorSource,
    style: defaultStyle()
  });

  map.ol.addLayer(vectorLayer);

  const layer = new SpxLayer(vectorLayer, {
    name: opts.name || 'GeoJSON',
    type: 'geojson',
    map,
    data: geojson
  });
  registerLayer(map, layer);
  return layer;
}

// -- Shapefile loader --

async function loadShapefile(map, source, opts = {}) {

  await ensureShp();

  let buffer;
  if (source instanceof ArrayBuffer) {
    buffer = source;
  } else if (source instanceof File || source instanceof Blob) {
    buffer = await source.arrayBuffer();
  } else if (typeof source === 'string') {
    const resp = await fetch(source);
    buffer = await resp.arrayBuffer();
  } else {
    throw new Error('Shapefile source must be an ArrayBuffer, File, Blob, or URL');
  }

  const geojson = await shp(buffer);
  // shpjs may return an array for multi-layer shapefiles
  const collection = Array.isArray(geojson) ? geojson[0] : geojson;

  const format = new ol.format.GeoJSON();
  const features = format.readFeatures(collection, {
    featureProjection: map.ol.getView().getProjection(),
    dataProjection: opts.crs || 'EPSG:4326'
  });

  const vectorSource = new ol.source.Vector({ features });
  const vectorLayer = new ol.layer.Vector({
    source: vectorSource,
    style: defaultStyle()
  });

  map.ol.addLayer(vectorLayer);

  const layer = new SpxLayer(vectorLayer, {
    name: opts.name || 'Shapefile',
    type: 'shp',
    map,
    data: collection
  });
  registerLayer(map, layer);
  return layer;
}

// -- GeoTIFF loader --

async function loadGeoTIFF(map, source, opts = {}) {


  let rasterLayer;

  if (typeof source === 'string') {
    // URL — use OL's native GeoTIFF source (supports COG streaming)
    const tifSource = new ol.source.GeoTIFF({
      sources: [{ url: source }],
      crossOrigin: 'anonymous'
    });
    rasterLayer = new ol.layer.WebGLTile({ source: tifSource });
  } else {
    // ArrayBuffer or File — parse and display as DataTile
    let buffer;
    if (source instanceof ArrayBuffer) {
      buffer = source;
    } else if (source instanceof File || source instanceof Blob) {
      buffer = await source.arrayBuffer();
    } else {
      throw new Error('GeoTIFF source must be a string URL, ArrayBuffer, File, or Blob');
    }

    // Use OL's GeoTIFF source with blob URL
    const blob = new Blob([buffer], { type: 'image/tiff' });
    const blobUrl = URL.createObjectURL(blob);
    const tifSource = new ol.source.GeoTIFF({
      sources: [{ url: blobUrl }]
    });
    rasterLayer = new ol.layer.WebGLTile({ source: tifSource });
  }

  map.ol.addLayer(rasterLayer);

  const layer = new SpxLayer(rasterLayer, {
    name: opts.name || 'GeoTIFF',
    type: 'tif',
    map
  });
  registerLayer(map, layer);
  return layer;
}

// -- Auto-detect loader --

async function autoLoad(map, file) {
  let name, ext;
  if (typeof file === 'string') {
    name = file.split('/').pop().split('?')[0];
  } else if (file instanceof File) {
    name = file.name;
  } else {
    throw new Error('autoLoad expects a File, URL string, or use a specific loader');
  }

  ext = (name.split('.').pop() || '').toLowerCase();

  if (ext === 'csv' || ext === 'tsv') return loadCSV(map, file);
  if (ext === 'geojson' || ext === 'json') {
    const text = file instanceof File ? await file.text() : await (await fetch(file)).text();
    return loadGeoJSON(map, text);
  }
  if (ext === 'zip' || ext === 'shp') return loadShapefile(map, file);
  if (ext === 'tif' || ext === 'tiff') return loadGeoTIFF(map, file);

  // Unknown format — try GDAL fallthrough
  if (typeof loadViaGDAL === 'function') {
    return loadViaGDAL(map, file);
  }
  throw new Error(`Unknown format: .${ext}. Try spx.gdal() for GDAL-supported formats.`);
}

// -- srtm.js --

// SRTM tile download, HGT parsing, mosaicing




const SRTM_BASE = 'https://s3.amazonaws.com/elevation-tiles-prod/skadi';
const TILE_SIZE = 3601; // SRTM GL1: 3601x3601 pixels per 1-degree tile
const MAX_TILES = 16;

// IndexedDB cache for gzipped SRTM tiles (~2.5 MB each)
const DB_NAME = 'spx-srtm';
const DB_VERSION = 1;

function openTileDB() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = () => req.result.createObjectStore('tiles', { keyPath: 'key' });
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function tileGet(key) {
  const db = await openTileDB();
  return new Promise((resolve) => {
    const tx = db.transaction('tiles', 'readonly');
    const req = tx.objectStore('tiles').get(key);
    req.onsuccess = () => resolve(req.result?.data ?? null);
    req.onerror = () => resolve(null);
  });
}

async function tilePut(key, data) {
  const db = await openTileDB();
  const tx = db.transaction('tiles', 'readwrite');
  tx.objectStore('tiles').put({ key, data, ts: Date.now() });
}

function tileKey(lat, lon) {
  const ns = lat >= 0 ? 'N' : 'S';
  const ew = lon >= 0 ? 'E' : 'W';
  const latStr = String(Math.abs(lat)).padStart(2, '0');
  const lonStr = String(Math.abs(lon)).padStart(3, '0');
  return `${ns}${latStr}${ew}${lonStr}`;
}

function tileUrl(lat, lon) {
  const key = tileKey(lat, lon);
  const ns = lat >= 0 ? 'N' : 'S';
  const latStr = String(Math.abs(lat)).padStart(2, '0');
  const folder = `${ns}${latStr}`;
  return `${SRTM_BASE}/${folder}/${key}.hgt.gz`;
}

function tilesForBbox(bbox) {
  const [west, south, east, north] = bbox;
  const tiles = [];
  for (let lat = Math.floor(south); lat < Math.ceil(north); lat++) {
    for (let lon = Math.floor(west); lon < Math.ceil(east); lon++) {
      tiles.push({ lat, lon });
    }
  }
  return tiles;
}

async function fetchAndParseHGT(lat, lon) {
  const key = tileKey(lat, lon);

  // Check IDB cache first
  let gzBuf = await tileGet(key);
  if (!gzBuf) {
    const resp = await fetch(tileUrl(lat, lon));
    if (!resp.ok) return null; // ocean or void tile
    gzBuf = await resp.arrayBuffer();
    tilePut(key, gzBuf); // fire-and-forget
  }

  // Decompress gzip
  const ds = new DecompressionStream('gzip');
  const decompressed = new Blob([gzBuf]).stream().pipeThrough(ds);
  const reader = decompressed.getReader();
  const chunks = [];
  let totalLen = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value);
    totalLen += value.length;
  }

  // Concatenate into single buffer
  const buffer = new Uint8Array(totalLen);
  let offset = 0;
  for (const chunk of chunks) {
    buffer.set(chunk, offset);
    offset += chunk.length;
  }

  // Parse big-endian Int16 → Float32
  const expectedSize = TILE_SIZE * TILE_SIZE;
  const dv = new DataView(buffer.buffer, buffer.byteOffset, buffer.byteLength);
  const data = new Float32Array(expectedSize);
  for (let i = 0; i < expectedSize; i++) {
    const val = dv.getInt16(i * 2, false); // big-endian
    data[i] = val === -32768 ? -9999 : val; // nodata
  }
  return data;
}

function mosaicTiles(tiles, tileData) {
  if (tiles.length === 1 && tileData[0]) {
    const t = tiles[0];
    return {
      data: tileData[0],
      width: TILE_SIZE,
      height: TILE_SIZE,
      bbox: [t.lon, t.lat, t.lon + 1, t.lat + 1]
    };
  }

  // Calculate mosaic dimensions
  const lats = tiles.map(t => t.lat);
  const lons = tiles.map(t => t.lon);
  const minLat = Math.min(...lats);
  const maxLat = Math.max(...lats);
  const minLon = Math.min(...lons);
  const maxLon = Math.max(...lons);

  const tilesX = maxLon - minLon + 1;
  const tilesY = maxLat - minLat + 1;
  // Tiles share border pixels, so mosaic size accounts for overlap
  const width = tilesX * (TILE_SIZE - 1) + 1;
  const height = tilesY * (TILE_SIZE - 1) + 1;

  const mosaic = new Float32Array(width * height).fill(-9999);

  for (let i = 0; i < tiles.length; i++) {
    const td = tileData[i];
    if (!td) continue;
    const t = tiles[i];

    const tileOffX = (t.lon - minLon) * (TILE_SIZE - 1);
    // SRTM tiles are stored north-to-south (row 0 = north edge)
    const tileOffY = (maxLat - t.lat) * (TILE_SIZE - 1);

    for (let row = 0; row < TILE_SIZE; row++) {
      for (let col = 0; col < TILE_SIZE; col++) {
        const val = td[row * TILE_SIZE + col];
        if (val !== -9999) {
          mosaic[(tileOffY + row) * width + (tileOffX + col)] = val;
        }
      }
    }
  }

  return {
    data: mosaic,
    width,
    height,
    bbox: [minLon, minLat, maxLon + 1, maxLat + 1]
  };
}

async function cacheList() {
  const db = await openTileDB();
  return new Promise((resolve) => {
    const tx = db.transaction('tiles', 'readonly');
    const req = tx.objectStore('tiles').getAll();
    req.onsuccess = () => resolve(req.result.map(r => ({
      key: r.key, size: r.data.byteLength, ts: r.ts
    })));
    req.onerror = () => resolve([]);
  });
}

async function cacheDelete(key) {
  const db = await openTileDB();
  const tx = db.transaction('tiles', 'readwrite');
  tx.objectStore('tiles').delete(key);
}

async function cacheClear() {
  const db = await openTileDB();
  const tx = db.transaction('tiles', 'readwrite');
  tx.objectStore('tiles').clear();
}

async function cacheSize() {
  const list = await cacheList();
  return { count: list.length, bytes: list.reduce((s, r) => s + r.size, 0) };
}

async function fetchSRTM(map, boundsOrLayer, opts = {}) {

  // Determine bbox
  let bbox;
  if (!boundsOrLayer) {
    bbox = map.bounds;
  } else if (Array.isArray(boundsOrLayer)) {
    bbox = boundsOrLayer;
  } else if (boundsOrLayer.bounds) {
    bbox = boundsOrLayer.bounds;
  } else {
    bbox = map.bounds;
  }

  const tiles = tilesForBbox(bbox);
  if (tiles.length > MAX_TILES) {
    console.warn(`SRTM: ${tiles.length} tiles needed (max ${MAX_TILES}). Zoom in or narrow extent.`);
    throw new Error(`Too many SRTM tiles (${tiles.length}). Max is ${MAX_TILES}. Zoom in.`);
  }

  // Fetch all tiles
  const tileData = [];
  for (let i = 0; i < tiles.length; i++) {
    const t = tiles[i];
    if (opts.onProgress) opts.onProgress(tileKey(t.lat, t.lon), i + 1, tiles.length);
    const data = await fetchAndParseHGT(t.lat, t.lon);
    tileData.push(data);
  }

  const mosaic = mosaicTiles(tiles, tileData);

  // Create DEM
  const dem = new DEM(mosaic.data, mosaic.width, mosaic.height, mosaic.bbox);

  // Render DEM to canvas and display as ImageStatic layer
  const canvas = renderDEMCanvas(dem);
  const extent = ol.proj.transformExtent(
    mosaic.bbox, 'EPSG:4326', map.ol.getView().getProjection()
  );

  const rasterLayer = new ol.layer.Image({
    source: new ol.source.ImageStatic({
      url: canvas.toDataURL(),
      imageExtent: extent
    })
  });

  map.ol.addLayer(rasterLayer);

  const layer = new SpxLayer(rasterLayer, {
    name: opts.name || 'SRTM',
    type: 'srtm',
    map,
    bounds: mosaic.bbox,
    data: dem
  });

  // Attach DEM methods to the layer for convenience
  layer.sample = (lat, lon) => dem.sample(lat, lon);
  layer.profile = (latA, lonA, latB, lonB, profileOpts) => dem.profile(latA, lonA, latB, lonB, profileOpts);
  layer.data = dem;
  layer.width = dem.width;
  layer.height = dem.height;
  layer.min = dem.min;
  layer.max = dem.max;
  layer.bbox = dem.bbox;

  registerLayer(map, layer);
  return layer;
}

// -- draw.js --

// Drawing interactions returning promises

async function drawOnMap(map, type, opts = {}) {

  const olType = {
    point: 'Point',
    polyline: 'LineString',
    polygon: 'Polygon',
    rectangle: 'Circle' // uses createBox geometry function
  }[type];

  if (!olType) throw new Error(`Unknown draw type: ${type}. Use point, polyline, polygon, or rectangle.`);

  const drawOpts = { type: olType };

  // Rectangle uses createBox geometry function
  if (type === 'rectangle') {
    drawOpts.geometryFunction = ol.interaction.Draw.createBox();
  }

  if (opts.maxPoints && type !== 'point' && type !== 'rectangle') {
    drawOpts.maxPoints = opts.maxPoints;
  }

  const source = new ol.source.Vector();
  const drawLayer = new ol.layer.Vector({ source });
  map.ol.addLayer(drawLayer);

  const draw = new ol.interaction.Draw({ source, ...drawOpts });
  map.ol.addInteraction(draw);

  return new Promise((resolve) => {
    draw.on('drawend', (e) => {
      map.ol.removeInteraction(draw);

      const geom = e.feature.getGeometry();
      let result;

      if (type === 'point') {
        const coord = ol.proj.toLonLat(geom.getCoordinates());
        result = { coord, geometry: geom };
      } else if (type === 'rectangle') {
        const ext = geom.getExtent();
        const [w, s] = ol.proj.toLonLat([ext[0], ext[1]]);
        const [e, n] = ol.proj.toLonLat([ext[2], ext[3]]);
        result = { extent: [w, s, e, n], geometry: geom };
      } else {
        const coords = geom.getCoordinates();
        // Convert to lon/lat
        const llCoords = type === 'polygon'
          ? coords[0].map(c => ol.proj.toLonLat(c))
          : coords.map(c => ol.proj.toLonLat(c));
        result = { coords: llCoords, geometry: geom };
      }

      // Remove draw layer after a short delay to show the drawn feature
      setTimeout(() => map.ol.removeLayer(drawLayer), 100);

      resolve(result);
    });
  });
}

// -- gdal.js --

// GDAL Wasm lazy loader, universal format fallthrough, DEM wrappers



const GDAL_JS_URL = 'https://cdn.jsdelivr.net/npm/gdal3.js@2/dist/package/gdal3.js';
const GDAL_DATA_URL = 'https://cdn.jsdelivr.net/npm/gdal3.js@2/dist/package/gdal3WebAssembly.data';
const GDAL_WASM_URL = 'https://cdn.jsdelivr.net/npm/gdal3.js@2/dist/package/gdal3WebAssembly.wasm';

let _gdalInstance = null;
let _gdalLoading = null;

async function loadGDAL() {
  if (_gdalInstance) return _gdalInstance;
  if (_gdalLoading) return _gdalLoading;

  _gdalLoading = (async () => {
    // Inject gdal3.js script
    await new Promise((resolve, reject) => {
      if (document.querySelector(`script[src="${GDAL_JS_URL}"]`)) {
        resolve();
        return;
      }
      const s = document.createElement('script');
      s.src = GDAL_JS_URL;
      s.onload = resolve;
      s.onerror = () => reject(new Error('Failed to load gdal3.js'));
      document.head.appendChild(s);
    });

    // Initialize GDAL
    if (typeof initGdalJs !== 'function') {
      throw new Error('gdal3.js loaded but initGdalJs not found');
    }
    _gdalInstance = await initGdalJs({
      paths: {
        wasm: GDAL_WASM_URL,
        data: GDAL_DATA_URL
      }
    });
    return _gdalInstance;
  })();

  return _gdalLoading;
}

// Universal format fallthrough via GDAL
async function loadViaGDAL(map, file) {
  const gdal = await loadGDAL();

  let fileObj;
  if (file instanceof File) {
    fileObj = file;
  } else if (typeof file === 'string') {
    const resp = await fetch(file);
    const blob = await resp.blob();
    const name = file.split('/').pop().split('?')[0] || 'data';
    fileObj = new File([blob], name);
  } else if (file instanceof ArrayBuffer || file instanceof Blob) {
    fileObj = new File([file], 'data');
  } else {
    throw new Error('GDAL input must be a File, URL, ArrayBuffer, or Blob');
  }

  const result = await gdal.open(fileObj);
  const ds = result.datasets[0];
  if (!ds) throw new Error('GDAL could not open the file');

  const info = await gdal.getInfo(ds);

  // Detect vector vs raster from info
  if (info.layers && info.layers.length > 0) {
    // Vector: convert to GeoJSON
    const output = await gdal.ogr2ogr(ds, ['-f', 'GeoJSON', '-t_srs', 'EPSG:4326']);
    const bytes = await gdal.getFileBytes(output);
    const text = new TextDecoder().decode(bytes);
    const geojson = JSON.parse(text);
    await gdal.close(ds);
    return loadGeoJSON(map, geojson, { name: fileObj.name });
  } else {
    // Raster: convert to GeoTIFF
    const output = await gdal.gdal_translate(ds, ['-of', 'GTiff']);
    const bytes = await gdal.getFileBytes(output);
    await gdal.close(ds);
    return loadGeoTIFF(map, bytes.buffer, { name: fileObj.name });
  }
}

// Build a minimal GeoTIFF from DEM Float32Array for GDAL input
function demToGeoTIFF(dem) {
  // Create a simple binary GeoTIFF with minimal headers
  // This is used as input for GDAL DEM processing tools
  const { data, width, height, bbox } = dem;
  const [west, south, east, north] = bbox;

  // We'll create a simple TIFF file
  // For simplicity, use raw Float32 data with geo metadata
  // GDAL can read ENVI .hdr + .dat pairs more easily
  const pixelSizeX = (east - west) / width;
  const pixelSizeY = (north - south) / height;

  // Build TIFF with IFD
  const dataBytes = data.length * 4;
  const headerSize = 512; // generous header allocation

  const buf = new ArrayBuffer(headerSize + dataBytes);
  const view = new DataView(buf);
  const u8 = new Uint8Array(buf);

  // TIFF header (little-endian)
  view.setUint16(0, 0x4949, true);  // II = little endian
  view.setUint16(2, 42, true);       // TIFF magic
  view.setUint32(4, 8, true);        // offset to first IFD

  // IFD at offset 8
  let ifdOffset = 8;
  const tags = [
    [256, 3, 1, width],              // ImageWidth
    [257, 3, 1, height],             // ImageLength
    [258, 3, 1, 32],                 // BitsPerSample
    [259, 3, 1, 1],                  // Compression = none
    [262, 3, 1, 1],                  // PhotometricInterpretation = MinIsBlack
    [273, 4, 1, headerSize],         // StripOffsets
    [277, 3, 1, 1],                  // SamplesPerPixel
    [278, 3, 1, height],             // RowsPerStrip
    [279, 4, 1, dataBytes],          // StripByteCounts
    [339, 3, 1, 3],                  // SampleFormat = floating point
  ];

  view.setUint16(ifdOffset, tags.length, true);
  ifdOffset += 2;

  for (const [tag, type, count, value] of tags) {
    view.setUint16(ifdOffset, tag, true);
    view.setUint16(ifdOffset + 2, type, true);
    view.setUint32(ifdOffset + 4, count, true);
    if (type === 3) view.setUint16(ifdOffset + 8, value, true);
    else view.setUint32(ifdOffset + 8, value, true);
    ifdOffset += 12;
  }

  // Next IFD offset = 0 (no more IFDs)
  view.setUint32(ifdOffset, 0, true);

  // Copy float data
  const floatView = new Float32Array(buf, headerSize, data.length);
  floatView.set(data);

  return new File([buf], 'dem.tif', { type: 'image/tiff' });
}

// High-level DEM wrappers using GDAL

async function gdalContour(dem, opts = {}) {
  const gdal = await loadGDAL();
  const interval = opts.interval || 100;
  const tifFile = demToGeoTIFF(dem.data ? dem : dem);

  const result = await gdal.open(tifFile);
  const ds = result.datasets[0];

  const args = ['-i', String(interval), '-f', 'GeoJSON'];
  if (opts.attribute) args.push('-a', opts.attribute);
  else args.push('-a', 'elev');

  const output = await gdal.gdal_contour(ds, args);
  const bytes = await gdal.getFileBytes(output);
  const text = new TextDecoder().decode(bytes);
  const geojson = JSON.parse(text);
  await gdal.close(ds);

  return geojson;
}

async function gdalSlope(dem) {
  const gdal = await loadGDAL();
  const tifFile = demToGeoTIFF(dem.data ? dem : dem);

  const result = await gdal.open(tifFile);
  const ds = result.datasets[0];

  const output = await gdal.gdaldem(ds, 'slope', []);
  const bytes = await gdal.getFileBytes(output);
  await gdal.close(ds);

  return bytes.buffer;
}

async function gdalAspect(dem) {
  const gdal = await loadGDAL();
  const tifFile = demToGeoTIFF(dem.data ? dem : dem);

  const result = await gdal.open(tifFile);
  const ds = result.datasets[0];

  const output = await gdal.gdaldem(ds, 'aspect', []);
  const bytes = await gdal.getFileBytes(output);
  await gdal.close(ds);

  return bytes.buffer;
}

async function gdalHillshade(dem, opts = {}) {
  const gdal = await loadGDAL();
  const azimuth = opts.azimuth || 315;
  const tifFile = demToGeoTIFF(dem.data ? dem : dem);

  const result = await gdal.open(tifFile);
  const ds = result.datasets[0];

  const output = await gdal.gdaldem(ds, 'hillshade', ['-az', String(azimuth)]);
  const bytes = await gdal.getFileBytes(output);
  await gdal.close(ds);

  return bytes.buffer;
}

